import {initTransformUI} from './transform-ui.js';
import {enclosureInspector,initEnclosureUI} from './enclosure-ui.js';
import {initPlacement} from './placement-ui.js';
import {initWorkbenchUI,exportHTML} from './ui.js';
import {parseLength,resizePart} from './dimensions.js';
import {driven,evaluatePose} from './motion.js';
import {VERSION,APP,CATALOG,MATERIALS,makePart,freshProject,demoProject,validateProject,inspect,bom,bomCSV,baseline,comparison,uid} from './model.js';
import {readSaved,saveProject,saveCheckpoint} from './storage.js';
import {initWorkspace} from './workspace.js';
import {initGeometry} from './geometry.js';
import {reviewProject} from './review.js';
import {texturesReady} from './rendering.js';
import {Studio} from './scene.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safePref=(key,fallback)=>{try{return localStorage.getItem('mockupbench-'+key)||fallback;}catch{return fallback;}};
const setPref=(key,value)=>{try{localStorage.setItem('mockupbench-'+key,value);}catch{}};
let transforms=null,placement=null,ui=null,workspace=null,lastRecovery=0,dimensionLinked=false,dimensionAnchor='center';
let project=freshProject(),selected=null,studio=null,history=[],future=[],findings=[],saveTimer,saveChain=Promise.resolve(),saveRevision=0,failedLoad=false;
let theme=safePref('theme','light'),advanced=safePref('mode','easy')==='advanced',reviewTab='fit';
if(!['light','dark','contrast'].includes(theme))theme='light';document.documentElement.dataset.theme=theme;
document.body.classList.toggle('advanced',advanced);$('#mode').value=advanced?'advanced':'easy';
if(innerWidth<=1100)document.body.classList.add('hide-inspector');if(innerWidth<=720)document.body.classList.add('hide-library');

const factor=()=>project.units==='in'?25.4:1;
const length=n=>+(n/factor()).toFixed(project.units==='in'?4:3);
const fmt=n=>Number(n).toLocaleString(undefined,{maximumFractionDigits:project.units==='in'?3:1});
const dimText=d=>d.map(n=>fmt(length(n))).join(' × ')+' '+project.units;
function notify(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function status(text,state='saved'){$('#saveState').dataset.state=state;$('#saveState').innerHTML=`<i></i> ${esc(text)}`;}
function copyState(v,key=''){if(key==='vertices')return v;if(Array.isArray(v))return v.map(a=>copyState(a));if(v&&typeof v==='object')return Object.fromEntries(Object.entries(v).map(([k,a])=>[k,copyState(a,k)]));return v;}
function snapshot(){return copyState(project);}
async function recoverSave(value=snapshot()){await saveCheckpoint(value);lastRecovery=Date.now();}
function checkpoint(){history.push(snapshot());if(history.length>30)history.shift();future=[];}
function save(){
 status('Unsaved','saving');const revision=++saveRevision;clearTimeout(saveTimer);
 saveTimer=setTimeout(()=>{status('Saving','saving');const value=snapshot();saveChain=saveChain.catch(()=>{}).then(async()=>{await saveProject(value);if(Date.now()-lastRecovery>300000)await recoverSave(value);}).then(()=>{if(revision===saveRevision)status('Saved locally');failedLoad=false;}).catch(err=>{status('Save failed · export JSON','error');notify('Local save failed. Export project JSON to keep your work. '+err.message);});},300);
}
function commit(action,{rebuild=true,inspector=true}={}){placement?.cancel();if(failedLoad)throw Error('Open a valid JSON backup or choose New Project before editing; the previous autosave could not be read.');const before=snapshot();try{action();validateProject(project);}catch(err){project=before;refresh();throw err;}history.push(before);if(history.length>30)history.shift();future=[];save();refresh({rebuild,inspector});}
function refresh({rebuild=true,inspector=true}={}){
 if(rebuild)workspace?.beforeRefresh?.();
 if(selected&&!selected.startsWith('@')&&!project.parts.some(p=>p.id===selected)&&!project.groups.some(g=>g.id===selected))selected=null;
 $('#projectTitle').value=project.title;$('#units').value=project.units;$('#partCount').textContent=project.parts.length;$('#summaryCount').textContent=`${project.parts.filter(a=>a.kind!=='space').length} components`;
 $('#sizeSummary').textContent=dimText([project.enclosure.w,project.enclosure.d,project.enclosure.h]);$('#gridLabel').textContent=project.units==='in'?'Grid = 0.394 in (10 mm)':'10 mm grid';
 $('#empty').hidden=project.parts.length>0||project.features.length>0;$('#undo').disabled=!history.length;$('#redo').disabled=!future.length;
 findings=reviewProject(evaluatePose(project));$('#reviewCount').textContent=findings.filter(a=>a.severity==='Review').length;
 renderAssembly();if(inspector)renderInspector();if(rebuild)studio?.setProject(project);studio?.select(selected);
}
function select(id,info){placement?.cancel();workspace?.beforeRefresh();studio?.applyPose({});const changed=selected!==id;workspace?.selection(id,info);selected=id;renderInspector();renderAssembly();if(changed)$('#inspectorPanel').scrollTop=0;studio?.select(id,{auto:true});if(innerWidth<=1100)ui?.panel('inspector',true,{persist:false});ui?.sync();}
function options(values,current){return Object.entries(values).map(([key,label])=>`<option value="${esc(key)}"${key===current?' selected':''}>${esc(label)}</option>`).join('');}
function field(label,prop,value,{type='text',min,max,step,disabled=false,placeholder='',cls=''}={}){return `<label class="${cls}">${esc(label)}<input data-prop="${prop}" type="${type}" value="${esc(value)}"${min!==undefined?` min="${min}"`:''}${max!==undefined?` max="${max}"`:''}${step!==undefined?` step="${step}"`:''}${disabled?' disabled':''} placeholder="${esc(placeholder)}"></label>`;}
function selectField(label,prop,values,value,cls=''){return `<label class="${cls}">${esc(label)}<select data-prop="${prop}">${options(values,value)}</select></label>`;}
function numFields(labels,prop,vals,rotation=false,disabled=false){return `<div class="fields">${labels.map((label,i)=>field(label,`${prop}.${i}`,rotation?+vals[i].toFixed(2):length(vals[i]),{type:rotation?'number':'text',step:rotation?1:undefined,disabled})).join('')}</div>`;}
function dimensionCard(p){return `<section class="inspector-section dimension-card"><h3>Dimensions <span>${project.units}</span><kbd title="Focus width">D</kbd></h3><div class="fields">${p.dims.map((n,i)=>`<label>${['Width X','Depth Y','Height Z'][i]}<input data-prop="dims.${i}" type="text" inputmode="text" value="${length(n)}" aria-label="${['Width','Depth','Height'][i]} dimension"${p.locked?' disabled':''}><span class="dimension-steppers"><button type="button" data-resize-axis="${i}" data-resize-step="-1" aria-label="Decrease ${['width','depth','height'][i]}"${p.locked?' disabled':''}>−</button><button type="button" data-resize-axis="${i}" data-resize-step="1" aria-label="Increase ${['width','depth','height'][i]}"${p.locked?' disabled':''}>＋</button></span></label>`).join('')}</div><label class="check"><input type="checkbox" data-dimension-option="linked"${dimensionLinked?' checked':''}> Keep proportions</label><details data-disclosure="resize-options"><summary>Resize options</summary><label>Keep this point fixed<select data-dimension-option="anchor">${options({center:'Center',bottom:'Bottom face',min:'Minimum XYZ corner',max:'Maximum XYZ corner'},dimensionAnchor)}</select></label><p class="hint">Accepts 50 mm, 2 in, or 1 1/2 in. Surface features retain their size; reference points scale with the body.</p></details></section>`;}
function renderInspector(){
 const p=project.parts.find(a=>a.id===selected),e=project.enclosure;$('#inspectorHeading').textContent=p?'Part inspector':selected?.startsWith('@')?'Enclosure · '+selected.slice(1):'Project enclosure';
 const extra=workspace?.inspectorHTML(selected);if(extra?.replace){$('#inspectorHeading').textContent='Subassembly';$('#inspectorContent').innerHTML=extra.replace;ui?.decorateInspector();return;}
 let html;
 if(p){html=`<section class="inspector-section"><div class="stack">${field('Part name','name',p.name)}</div><span class="tag">${esc(p.kind==='mesh'?'Imported model':p.category||'Custom')} · ${p.confidence==='placeholder'?'illustrative dimensions':esc(p.confidence)}</span><div class="mini-actions"><button data-action="duplicate">Duplicate</button><button data-action="delete" class="danger">Delete</button></div></section>
 ${dimensionCard(p)}
 ${placement?.inspectorHTML(p)||''}
 <section class="inspector-section transform-card"><h3>3D transform</h3><p class="hint">Select a part for handles. <kbd>G</kbd> Move · <kbd>R</kbd> Rotate · drag away from handles to orbit.</p>${transforms?.inspectorHTML(p)||''}<h3 class="transform-heading">World center (${project.units})</h3>${numFields(['X','Y','Z'],'pos',p.pos,false,p.locked||driven(project,p.id))}<div class="mini-actions"><button data-action="floor"${p.locked?' disabled':''}>Rest on base</button><button data-action="center"${p.locked?' disabled':''}>Center X / Y</button></div><h3 class="transform-heading">Rotation · XYZ (°)</h3>${numFields(['X','Y','Z'],'rot',p.rot,true,p.locked||driven(project,p.id))}<div class="mini-actions"><button data-action="rotate90"${p.locked?' disabled':''}>Rotate Z 90°</button><button data-action="lock">${p.locked?'Unlock':'Lock'} position</button></div><p class="hint">X/Y origin is the enclosure center. Z = 0 is the outside bottom. Positive Y is toward the back. ${p.locked?'Unlock position to move.':driven(project,p.id)?'Use Joints & motion for this body.':'Escape cancels a handle drag.'}</p></section>
 <section class="inspector-section"><h3>Appearance</h3><div class="material-row"><select data-prop="material" aria-label="Part material">${options(MATERIALS,p.material)}</select><input data-prop="color" type="color" aria-label="Part color" value="${p.color}"></div></section>
 <section class="inspector-section"><details${advanced?' open':''}><summary>Part record & evidence</summary><div class="stack">${selectField('Part type','origin',{cots:'COTS component',custom:'Custom part'},p.origin)}${selectField('Dimension basis','confidence',{placeholder:'Placeholder — needs verification',datasheet:'Supplier drawing / datasheet',measured:'Measured part'},p.confidence)}${field('Manufacturer','manufacturer',p.manufacturer)}${field('Part number','partNumber',p.partNumber)}${field('Source / drawing reference','source',p.source,{placeholder:'URL, filename, or drawing number'})}${field('Unit cost (your project currency)','cost',p.cost??'',{type:'number',min:0,step:.01})}${field('Load (W) — leave blank if unknown','loadW',p.loadW??'',{type:'number',min:0,step:.1})}<label>Part notes<textarea data-prop="notes">${esc(p.notes)}</textarea></label><button data-action="savePart">Save as reusable part</button></div></details></section>`;}
 else{html=`<section class="inspector-section"><h3>Build around your parts</h3><p class="muted">Set the outside dimensions and panel thickness. The workspace supports products up to 36 inches on each axis.</p><label class="check" style="margin-top:12px"><input type="checkbox" data-prop="enclosure.enabled"${e.enabled?' checked':''}> Show enclosure</label><div class="fields">${['w','d','h'].map((k,i)=>field(['Width X','Depth Y','Height Z'][i]+` (${project.units})`,`enclosure.${k}`,length(e[k]),{type:'text'})).join('')}</div><div class="fields two">${field(`Thickness (${project.units})`,'enclosure.t',length(e.t),{type:'text'})}<label>Inside height<input readonly value="${fmt(length(e.h-(e.closure?.type==='slide'?3:2)*e.t))} ${project.units}"></label></div><p class="hint">Inside: ${dimText([e.w-2*e.t,e.d-2*e.t,e.h-(e.closure?.type==='slide'?3:2)*e.t])}</p></section>
 ${enclosureInspector(e,esc)}<section class="inspector-section"><h3>Enclosure finish</h3><div class="material-row"><select data-prop="enclosure.material" aria-label="Enclosure material">${options(MATERIALS,e.material)}</select><input data-prop="enclosure.color" type="color" aria-label="Enclosure color" value="${e.color}"></div><p class="hint">Panels retain their surface features when you change closure style. Closure geometry is for concept layout.</p></section>
 <section class="inspector-section"><details data-disclosure="project-brief"><summary>Project brief</summary><div class="stack">${field('Client / project reference','project.client',project.client)}${selectField('Power arrangement','project.power',{'Battery':'Battery','AC mains':'AC mains','External DC':'External DC','Battery + AC':'Battery + AC','Unspecified':'Unspecified'},project.power)}<label>Concept notes<textarea data-prop="project.notes" placeholder="What are you building?">${esc(project.notes)}</textarea></label></div></details></section>

 <section class="inspector-section"><button class="wide" data-action="review">Review & project evidence ↗</button><p class="hint">Client views, parts lists, and a printable design review are under Export.</p></section>`;}
 $('#inspectorContent').innerHTML=(extra?.prepend||'')+html+(extra?.append||'');ui?.decorateInspector();
}
function renderAssembly(){
 if(workspace){$('#assemblyList').innerHTML=workspace.assemblyHTML();ui?.decorateInspector();return;}
 $('#assemblyList').innerHTML=project.parts.length?project.parts.map(p=>`<div class="assembly-row${p.id===selected?' selected':''}"><button data-select="${esc(p.id)}" title="${esc(p.name)}"><i class="swatch" style="--swatch:${p.color}"></i><span class="name">${esc(p.name)}${p.locked?' <small> · locked</small>':''}</span></button><button data-visible="${esc(p.id)}" aria-label="${p.visible?'Hide':'Show'} ${esc(p.name)}">${p.visible?'Hide':'Show'}</button></div>`).join(''):'<p class="inset muted">No parts yet. Choose a component from the library or import an STL.</p>';
}
let reusable=[];try{reusable=JSON.parse(safePref('parts','[]'));if(!Array.isArray(reusable))reusable=[];reusable=reusable.map(a=>validateProject({...freshProject(),parts:[a]}).parts[0]);}catch{reusable=[];}
function art(kind){const shape=kind==='cylinder'||kind==='motor'?'<path d="M33 15v20c0 12 42 12 42 0V15"/><ellipse cx="54" cy="15" rx="21" ry="9"/><path d="M40 10v27M48 7v24" fill="none" opacity=".3"/>':kind==='pcb'?'<path d="m15 25 39-18 39 16-39 20z"/><path d="m38 24 15-7 15 6-15 7z" fill="#273c35"/><path d="m28 21 13-6m25 14 13-6m-51 5 13-6" fill="none" stroke="#d5be7a" stroke-width="4"/>':kind==='display'?'<path d="m21 17 48-9 21 22-48 10z"/><path d="m29 18 35-6 15 16-35 6z" fill="#8aacaa"/><path d="m42 23 19-4" fill="none" stroke="#d8ebe0" stroke-width="2"/>':kind==='bracket'?'<path d="m30 38 45-12-4-24-7 2 3 20-40 11z"/><path d="m30 38 14 9 46-13-15-8"/>':'<path d="m23 18 38-12 24 13v20l-37 12-25-13z"/><path d="m23 18 25 13 37-12M48 31v20" fill="none" opacity=".6"/>';return `<svg viewBox="0 0 110 58" aria-hidden="true">${shape}</svg>`;}
function renderCatalog(){const query=$('#search').value.toLowerCase(),cat=$('#category').value,source=$('#catalogSource')?.value||'all';let list=CATALOG.filter(p=>(cat==='All components'||p.category===cat)&&(source==='all'||(source==='interface')===(p.catalogSource==='InterfaceBench'))&&query.split(/\s+/).every(word=>(p.name+' '+p.category+' '+(p.catalogSource||'')+' '+(p.tags||[]).join(' ')).toLowerCase().includes(word)));if($('#catalogCount'))$('#catalogCount').textContent=list.length+' / '+CATALOG.length+' components';if($('#resetCatalog'))$('#resetCatalog').hidden=!query.trim()&&cat==='All components'&&source==='all';let html=list.map(p=>`<button class="part-card" draggable="true" title="Drag onto a panel, or click to place" data-add="${p.key}" style="--swatch:${p.color}"><span class="plus">＋</span><span class="part-art">${art(p.kind)}</span><strong>${esc(p.name)}</strong><small>${esc(dimText(p.dims))}</small></button>`).join('');if(source!=='interface'&&reusable.length&&(cat==='All components'||cat==='Custom'))html+=reusable.filter(p=>p.name.toLowerCase().includes(query)).map(p=>`<button class="part-card" draggable="true" title="Drag onto a panel, or click to place" data-reuse="${esc(p.id)}" style="--swatch:${p.color}"><span class="plus">＋</span><span class="part-art">${art(p.kind)}</span><strong>${esc(p.name)}</strong><small>My saved part</small></button>`).join('');$('#catalog').innerHTML=html||'<div class="panel-empty"><strong>No matching components</strong><p>Try a shorter name or clear the filters.</p><button id="clearCatalogEmpty">Clear filters</button></div>';}
function catalogPart(key,template){const p=template?{...structuredClone(template),id:uid(),pos:[0,0,0],rot:[0,0,0],groupId:'',visible:true,locked:false}:makePart(key);delete p.surfaceRef;return p;}
function addPart(key,template){if(placement?.ignoreClick())return;if(project.parts.length>=500)return notify('The project limit is 500 parts.');const p=catalogPart(key,template);if(studio&&(project.enclosure.enabled||project.parts.some(a=>a.visible&&a.kind!=='space')))return placement.begin(p);p.pos=[0,0,project.enclosure.t+p.dims[2]/2];commit(()=>{project.parts.push(p);selected=p.id;});notify(`${p.name} added at the base center. Face placement needs the 3D view and a visible enclosure or another component.`);}
function replaceProject(p){placement?.cancel();p=validateProject(p);recoverSave().catch(err=>notify('Checkpoint failed: '+err.message));checkpoint();project=p;workspace?.reset();selected=null;failedLoad=false;studio?.setExplode(0);$('#explode').value=0;$('#explodeValue').textContent='0%';save();refresh();renderCatalog();studio?.fit('iso');$('#camera').value='iso';}
function openModal(title,html){placement?.cancel();ui?.beforeDialog();$('#modalTitle').textContent=title;$('#modalBody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function download(blob,name){const a=document.createElement('a');const url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
const fileStem=()=>project.title.replace(/[^a-z0-9_-]+/gi,'-').replace(/^-|-$/g,'').slice(0,100)||'mockupbench';
function jsonExport(){download(new Blob([JSON.stringify({...project,version:VERSION},null,2)],{type:'application/json'}),`${fileStem()}.mockupbench.json`);notify('Project JSON exported, including imported meshes.');}
async function pngExport(){if(!studio){notify('The 3D renderer is unavailable.');return;}try{await texturesReady(project.features);if(studio.geometryErrors.length)throw Error('Resolve geometry errors before exporting.');const a=document.createElement('a');a.href=studio.snapshot();a.download=`${fileStem()}-${studio.shellMode}.png`;a.click();notify('PNG exported from the current view.');}catch(err){notify(err.message);}}
function csvExport(){download(new Blob(['\ufeff'+bomCSV(project)],{type:'text/csv;charset=utf-8'}),`${fileStem()}-parts.csv`);notify('Bill of materials exported.');}
function stlExport(){if(!studio)return notify('The 3D renderer is unavailable.');download(new Blob([studio.exportSTL()],{type:'model/stl'}),`${fileStem()}-concept-mm.stl`);notify('Concept STL exported in millimeters.');}
function exportDialog(){openModal('Take it off the bench',exportHTML());}
function tableHTML(){const rows=bom(project);return `<div class="table-wrap"><table><thead><tr><th>Part</th><th>Qty</th><th>Size (${project.units})</th><th>Basis</th><th>Unit cost</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name)}<small>${esc([p.manufacturer,p.partNumber].filter(Boolean).join(' · '))}</small></td><td>${p.quantity}</td><td>${p.dims.map(n=>esc(fmt(length(n)))).join(' × ')}</td><td>${esc(p.confidence)}</td><td>${p.cost===null?'—':esc(p.cost.toFixed(2))}</td></tr>`).join('')}</tbody></table></div>`;}
function showReview(tab=reviewTab){
 reviewTab=tab;const tabs=`<div class="review-tabs">${[['fit','Fit observations'],['bom','Parts list'],['evidence','Notes & evidence'],['baseline','Baseline']].map(([key,text])=>`<button data-review-tab="${key}" class="${tab===key?'active':''}">${text}</button>`).join('')}</div>`;let content='';
 if(tab==='fit')content=`<p>Checks use conservative oriented bounding envelopes at the saved joint pose, including hidden parts. Cutouts do not reduce these envelopes. Overlap may be intentional, especially at mounts and panel controls. Imported meshes and rotated parts may produce false positives.</p><div class="note">Power: <strong>${esc(project.power)}</strong>. Cable paths and entered load estimates are available under Wiring & power. It does not validate wiring, battery protection, thermal performance, or AC safety.</div>${findings.length?findings.map((f,i)=>`<div class="finding"><span class="badge">${f.severity}</span><div><button data-finding="${i}">${esc(f.text)}</button><small>Confidence: ${f.confidence}</small>${f.key&&!f.key.startsWith('feature|')&&f.ids.length?`<button data-accept="${i}">${f.severity==='Accepted'?'Reopen observation':'Accept intentional fit'}</button>`:''}</div></div>`).join(''):'<p>No envelope conflicts found. This is a layout check, not proof of physical fit.</p>'}`;
 if(tab==='bom'){const parts=bom(project),known=parts.filter(p=>p.cost!==null),total=known.reduce((s,p)=>s+p.cost*p.quantity,0);content=tableHTML()+`<div class="note">Entered cost subtotal: <strong>${total.toFixed(2)}</strong> in your project currency. ${parts.filter(a=>a.cost===null).length} line items have no cost. Enclosure panels, tax, labor, and shipping are excluded.</div><button data-export="csv">Export parts CSV</button>`;}
 if(tab==='evidence')content=`<p>Keep design assumptions separate from confirmed information. Part-specific drawing references belong in the part inspector.</p><div class="stack"><label>Assumptions<textarea id="assumptions" rows="4">${esc(project.assumptions)}</textarea></label><label>Evidence / references<textarea id="evidence" rows="4">${esc(project.evidence)}</textarea></label><button id="saveEvidence" class="primary">Save notes</button></div>`;
 if(tab==='baseline'){const changes=comparison(project);content=project.baseline?`<p>Baseline: <strong>${esc(project.baseline.name)}</strong><br>${esc(project.baseline.date)}</p>${changes.length?`<ul>${changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>`:'<p>No part or enclosure changes since the baseline.</p>'}`:'<p>Capture a reference state before revising a client concept. Compare added, removed, and changed parts plus enclosure settings.</p>';content+='<button id="captureBaseline" class="primary">'+(project.baseline?'Replace baseline':'Capture baseline')+'</button>';}
 openModal('Review the assembly',tabs+content);
}
async function report(){if(!studio)return notify('A 3D view is required for the report image.');try{await texturesReady(project.features);if(studio.geometryErrors.length)throw Error('Resolve geometry errors before printing.');const image=studio.snapshot();$('#printReport').innerHTML=`<h1>${esc(project.title)}</h1><div class="report-meta">${esc(project.client||'Product concept')} · ${new Date().toLocaleDateString()} · MOCKUPBENCH v${VERSION}</div><p>${esc(project.notes)}</p><img src="${image}" alt="Current 3D assembly view"><p class="print-note">View: ${esc(studio.shellMode)}, explosion ${Math.round(studio.explode*100)}%. Image reflects visibility settings; parts list includes hidden components. Geometry is illustrative unless independently verified.</p><h2>Project envelope</h2><p>Outside: ${dimText([project.enclosure.w,project.enclosure.d,project.enclosure.h])}\nPanel thickness: ${fmt(length(project.enclosure.t))} ${project.units} · Material: ${esc(project.enclosure.material)}\nPower arrangement: ${esc(project.power)}</p><h2>Bill of materials</h2>${tableHTML()}<p class="print-note">Costs, where entered, use the project currency. Enclosure panels, tax, labor and shipping are excluded.</p><h2>Fit observations</h2><p class="print-note">Conservative bounding-envelope checks at the saved joint pose; unsaved motion previews are excluded and overlaps may be intentional. These are not collision proofs or electrical, thermal, or safety validation.</p>${findings.length?`<ul>${findings.map(f=>`<li>${esc(f.severity)} · ${esc(f.text)} [${esc(f.confidence)}]</li>`).join('')}</ul>`:'<p>No bounding-envelope conflicts found.</p>'}<h2>Assumptions</h2><p>${esc(project.assumptions||'None recorded.')}</p><h2>Evidence & references</h2><p>${esc(project.evidence||'None recorded.')}</p>${workspace?.reportExtras()||''}${project.parts.filter(a=>a.source||a.notes).map(a=>`<p><strong>${esc(a.name)}</strong> — ${esc(a.source)}${a.notes?'\n'+esc(a.notes):''}</p>`).join('')}<p class="print-note">Concept mockup · dimensional verification, fabrication detail, electrical design and testing remain separate activities.</p>`;$('#modal').close();requestAnimationFrame(()=>requestAnimationFrame(()=>window.print()));}catch(err){notify(err.message);}}
function helpDialog(){openModal('MOCKUPBENCH · v'+VERSION,`<p>Build a client concept from real supplier models and custom parts, then present and export the assembly.</p><h3>A calmer workbench</h3><p>Use Add for components and custom parts, Surface for cutouts and artwork, Assemble for groups, joints and wiring, and Inspect for measurements and saved views. Export groups client presentations, build files and an editable backup. Units, Easy/Advanced controls and themes are in the menu beside the project title.</p><p>Drag either panel divider to resize it; arrow keys adjust a focused divider and Home resets its width. Desktop panel widths and visibility are remembered. Focus view gives the model more room; press Escape to return. On a phone, use the panel buttons to open a drawer and tap outside or press Escape to close it. Parts tabs and tool menus support arrow keys.</p><h3>Place parts directly</h3><p>Drag any catalog part onto a flat enclosure or component face and release. A translucent preview aligns the selected part face with the target. Click a library card, then click a face for the same workflow without dragging; keyboard users can choose the surface above the viewport and use Place part. Inside faces, outside faces, panel edges and other components are available. Select the appropriate Open/Closed view before starting, or choose a surface from the list.</p><p>Exact placement accepts millimeters, inches and fractions. Across U and Along V measure from the face center; Gap lifts a part off the panel or recesses it with a negative value. Choose which part face rests against the panel. Grid snap includes center and edge alignment; Alt bypasses it. Arrow keys nudge the preview when focus is on the viewport or a placement action button (Shift for 10×, Alt for 0.1×); R turns 90°, Enter places, and Escape cancels. Use the camera selector, scroll to zoom, or right-drag to pan while placing.</p><p>Once placed, use Surface position for offsets, Center, Flush or Slide on surface. Slide locks the movement to the current mounting plane. Snap to another face changes the reference. Use 3D transform for free movement and exact world coordinates. Each drop or applied slide is one undoable action. The reference saves with project JSON; it does not create a motion joint or follow later target changes. Panel overhangs are flagged and may be intentional. Fit checks remain separate.</p><h3>Three-axis move and rotate</h3><p>Select an unlocked, independently positioned part to show its handles. Press G for Move or R for Rotate. Drag an X/Y/Z arrow, a plane square or a rotation ring. Handle axes switches between world and part axes. Drag away from the handles to orbit. The inspector has exact position and rotation fields; position accepts mm, inches and fractions.</p><p>Snap nearby aligns nominal centers, edges and touching faces of visible parts and enclosure panels. A green target and live readout show the match. Snap increments &amp; gap sets movement, rotation and contact spacing; 0 is free. Hold Alt to bypass snapping. Escape cancels a drag; release commits one undoable edit. For exact face orientation, choose Snap to a face, select the target and mounting face, then enter U/V offsets, turn and gap. References save with the project but do not create persistent mates or collision physics. Joint-driven parts use joint controls.</p><h3>Start here</h3><ol><li>Add a component, import STL / STEP / GLB, or create a custom part.</li><li>Select a part or enclosure panel. Add cutouts, SVG profiles, decals or raised/recessed lettering.</li><li>Use Assembly checkboxes to group parts; save the group to the reusable library.</li><li>Arrange with exact dimensions, transforms, alignment and measurements.</li><li>Add cable routes, record power assumptions, then save client views and variants.</li><li>Export project JSON, client PNG / GLB / MP4, engineering drawings, a printable review, BOM or nominal fabrication profiles.</li></ol><h3>Edit applied details</h3><p>Surface → Edit applied features lists every existing cutout, pocket, decal and text feature, including hidden ones. Search or filter by host, then Edit. Applied features also appear first in the selected host’s inspector. Double-click a decal to edit it, or a host to browse its features. Change dimensions, placement, depth, operation, text or artwork; the face preview updates as you type. Preview in 3D is temporary. Save changes keeps the same feature and operation order; Cancel restores the saved model. Undo is available.</p><h3>Enclosure styles</h3><p>Select Enclosure above the inspector, then choose Lift-off, Internal screw posts, External screw tabs, Sliding, Pin-hinged or Snap-fit lid. Adjust closure dimensions accepts mm, inches and fractions. Open view slides or swings the appropriate lid. Transparent and exploded views reveal posts, tabs, grooves, knuckles and clips. Generated geometry carries into STL, GLB, MP4 and engineering drawings, with closure dimension registers.</p><p>Style changes retain applied features at their face coordinates. Recheck placement after changing panel sizes. Box dimensions exclude external tabs and hinge hardware. During part placement, open hinged/sliding lids switch to Transparent at their saved position. Loose screws and threads are not modeled; snap elasticity and material strength are not simulated. Use explicit joints to move attached subassemblies. Panels with 3D closure details use STL or engineering drawings instead of flat SVG/DXF profiles.</p><h3>Motion, harnesses and quick sizing</h3><p>Use Joints & motion for fixed, hinge, slider, screw, cylindrical, ball and planar joints. Link rotary joints by gear ratio or a rotary joint to a rack slider by pitch diameter. Play previews the limits; Keep pose saves. Wiring & power → Custom & reusable harnesses manages branches, connector pins, conductors and saved harnesses. Size fields accept mm, inches and fractions; press D to focus Width, and use Keep proportions or a fixed resize anchor.</p><p>The catalog includes all 267 InterfaceBench definitions and 20 additional motion components. InterfaceBench models are illustrative 3D envelopes; their original cutouts and source notes are available in the inspector.</p><h3>MP4 product presentation</h3><p>Export → MP4 presentation starts closed, fades the enclosure transparent for a full 360° orbit, explodes the assembly for a second 360° orbit, then reassembles for a studio finish. Preview or scrub before rendering. Choose 720p/1080p, 24/30 fps, 20–60 seconds, studio background and Standard/High quality. High supersamples for cleaner edges. Rendering and H.264 encoding stay local. Download the finished MP4 before closing the dialog.</p><p>The movie uses placed positions with enabled enclosure panels closed, independent of joint playback and the working camera. Hidden physical parts are included by default. Harnesses hide during the explosion. Realism depends on model and artwork detail; the renderer uses physically based studio lighting and reflections.</p><h3>Engineering drawing package</h3><p>Export → Engineering drawings produces a downloadable PDF and a ZIP with the PDF, individual SVG sheets and an exact numeric dimension register. The set starts with a shaded 3D isometric view, then top, bottom, left, right, front and back views. Component sheets, surface layouts, body sizes, placements, cutouts, text, patterns, custom profiles, reference points and wiring dimensions follow.</p><p>Choose A3, A4, Tabloid or Letter paper, mm or inches, precision, scale and title-block details. Preview any sheet before downloading. Views use the saved joint pose and include hidden physical components by default. Surface coordinates are measured from face center. Print at 100%. All dimensions are nominal model values; supplier details, tolerances, fits and manufacturing specifications need explicit source data. Small nonzero dimensions retain significant digits even when they fall below the chosen decimal precision.</p><h3>Controls</h3><p>Drag to orbit · right-drag to pan · scroll to zoom. Shift-click or Assembly checkboxes select multiple parts. Numeric fields are available for every transform. Front is negative Y; Z is up. Surface coordinates are viewed from outside the selected face.</p><p>G: move · R: rotate · F: fit · Delete: remove selected part · Ctrl/Cmd+Z: undo · Ctrl/Cmd+Shift+Z: redo · Ctrl/Cmd+D: duplicate · Ctrl/Cmd+S: export project. Return Explode to 0% before editing positions or measuring.</p><h3>Data and recovery</h3><p>Projects and reusable assemblies save locally in IndexedDB. Checkpoints retain the five most recent snapshots before project replacement and periodically while editing. JSON embeds models and decals. Export JSON for backups outside this browser. Clear browser data only after exporting your work.</p><h3>Supplier workflow</h3><p>McMaster-Carr, DigiKey and Mouser catalog links open externally. Download available CAD, import it here, and retain supplier and manufacturer part numbers. Model processing happens locally. No supplier account is required for the editor. Model availability and download access depend on the supplier.</p><h3>Scope</h3><p>The enclosure supports 36 inches per axis. STEP becomes tessellated meshes; parametric history and STEP export are not included. GLB imports preserve mesh colors, not source textures or animation. Cutouts and lettering use real solid operations on panels, blocks, cylinders, brackets and closed imported meshes. Decals project onto a flat face. Imported open meshes cannot receive solid edits. SVG/DXF exports describe nominal planar profiles without machining compensation.</p><p>Fit checks use conservative component envelopes. Wiring and power features are layout and entered-data estimates. Joint motion is kinematic and does not simulate forces, collisions, backlash or cable strain. Overlapping components in assembly STL remain separate solids. Section planes affect only the displayed view.</p><h3>Development roadmap</h3><table><tr><th>Batch</th><th>Delivered</th></tr><tr><td>0.2</td><td>Local STEP/GLB import and supplier references</td></tr><tr><td>0.3</td><td>Precision tools and reusable nested assemblies</td></tr><tr><td>0.4–0.5</td><td>Custom profiles, cutouts, decals, emboss/deboss</td></tr><tr><td>0.6–0.8</td><td>Cable routing, power assumptions, variants and fabrication/client exports</td></tr><tr><td>0.9–1.0</td><td>Recovery, migration, offline package and regression coverage</td></tr></table><p><strong>Release candidate:</strong> automated checks pass; the final v1.6 browser/WebGL/placement/MP4/drawing-download/offline/print acceptance pass is pending.</p><p>1.1 delivered: joint motion and coupling, reusable harnesses, complete InterfaceBench catalog, motion components and direct dimension entry.</p><p>1.2 delivered: cinematic MP4 export with two full orbits, reassembly, studio rendering, adjustable quality and a scrubbable preview.</p><p>1.2.1 cleanup: task menus, clearer search and exports, prominent dimensions, remembered panel sizing, mobile drawers, consistent themes and keyboard/focus handling.</p><p>1.3 delivered: drag-to-surface placement, preview alignment, face/grid/center/edge snapping, exact offsets and gap, reusable placement references, plane-constrained sliding, and click/tap/keyboard alternatives.</p><p>1.4 delivered: engineering drawing PDF and SVG packages, seven assembly views, dimensioned component and surface sheets, saved-pose coordinates and wiring registers.</p><p>1.5 delivered: searchable applied-feature editing, draft previews, preserved operation order, and configurable lift-off, screw, sliding, hinged and snap-fit enclosures.</p><p>1.6 delivered: automatic three-axis move/rotate handles, world/part axes, nearby center/edge/contact snapping, exact component-to-component face alignment, live coordinates and one-drag undo.</p><p>Next: curved-surface artwork, parametric STEP export, advanced joinery and authenticated supplier procurement integrations.</p><p class="fine">All runtime libraries are bundled locally. Third-party notices and release verification details are in README.md and vendor/.</p>`);}


$('#inspectorContent').addEventListener('keydown',e=>{const prop=e.target.dataset.prop||'';if(e.key==='Enter'&&/^((dims|pos|rot)\.[012]|enclosure\.[wdht])$/.test(prop)){e.preventDefault();e.target.blur();const next=$('[data-prop="'+prop+'"]');next?.focus();next?.select();}});
$('#inspectorContent').addEventListener('change',event=>{
 const el=event.target,prop=el.dataset.prop;if(el.dataset.dimensionOption){if(el.dataset.dimensionOption==='linked')dimensionLinked=el.checked;else dimensionAnchor=el.value;return;}if(!prop)return;let value=el.type==='checkbox'?el.checked:el.value;
 if(el.type==='number'){
  if(el.value.trim()===''){if(['cost','loadW'].includes(prop))value=null;else{notify('Enter a numeric value.');renderInspector();return;}}
  else{value=Number(el.value);if(!Number.isFinite(value)){notify('Enter a finite numeric value.');renderInspector();return;}}
 }

 const p=project.parts.find(a=>a.id===selected);
 if(prop.startsWith('enclosure.')){
  const key=prop.split('.')[1];if(['w','d','h','t'].includes(key)){try{value=parseLength(value,project.units);}catch(err){notify(err.message);renderInspector();return;}}const next={...project.enclosure,[key]:value};
  if([next.w,next.d,next.h].some(n=>n<5||n>914.4000001)||next.t<.1||next.t*2>=Math.min(next.w,next.d,next.h)){notify('Use outside dimensions from 5 to 914.4 mm, and thickness under half the smallest dimension.');renderInspector();return;}
  try{commit(()=>project.enclosure=next);}catch(err){notify(err.message);renderInspector();}
 }else if(prop.startsWith('project.'))commit(()=>project[prop.split('.')[1]]=String(value).slice(0,12000),{rebuild:false});
 else if(p){
  if(/^(dims|pos|rot)\./.test(prop)){const [key,i]=prop.split('.');if(key==='dims'){try{const size=parseLength(value,project.units);if(driven(project,p.id)&&dimensionAnchor!=='center')throw Error('Use Center anchoring for a body positioned by a joint.');commit(()=>resizePart(p,+i,size,{linked:dimensionLinked,anchor:dimensionAnchor}));}catch(err){notify(err.message);renderInspector();}return;}if(driven(project,p.id)){notify('Use joint controls to move this body.');renderInspector();return;}if(key==='pos'){try{value=parseLength(value,project.units);}catch(err){notify(err.message);renderInspector();return;}}if(p.locked){notify('Unlock the part before moving or resizing.');return;}if((key==='dims'&&(value<.01||value>5000))||(key==='pos'&&Math.abs(value)>10000)||(key==='rot'&&Math.abs(value)>3600)){notify('Value is outside the supported range.');renderInspector();return;}commit(()=>p[key][+i]=value);}
  else{if((prop==='cost'||prop==='loadW')&&value!==null&&(value<0||value>1e6)){notify('Enter a value between 0 and 1,000,000.');renderInspector();return;}commit(()=>p[prop]=typeof value==='string'?value.slice(0,5000):value);}
 }
});
$('#inspectorContent').addEventListener('click',event=>{const stepper=event.target.closest('[data-resize-axis]');if(stepper){const p=project.parts.find(a=>a.id===selected);try{if(driven(project,p.id)&&dimensionAnchor!=='center')throw Error('Use Center anchoring for a joint body.');commit(()=>resizePart(p,+stepper.dataset.resizeAxis,p.dims[+stepper.dataset.resizeAxis]+Number(stepper.dataset.resizeStep)*(project.units==='in'?2.54:1),{linked:dimensionLinked,anchor:dimensionAnchor}));}catch(err){notify(err.message);}return;}const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;const p=project.parts.find(a=>a.id===selected);if(action==='review')return showReview();if(!p)return;
 if(action==='duplicate'){if(project.parts.length>=500)return notify('The project limit is 500 parts.');commit(()=>{const copy=workspace.duplicate(p);selected=copy.id;});}
 if(action==='delete')commit(()=>{workspace.remove([selected]);selected=null;});
 if(action==='lock')commit(()=>p.locked=!p.locked);
 if(['rotate90','center','floor'].includes(action)&&driven(project,p.id)){notify('Use joint controls to move this body.');return;}
 if(action==='rotate90'&&!p.locked)commit(()=>p.rot[2]=(p.rot[2]+90)%360);
 if(action==='center'&&!p.locked)commit(()=>{p.pos[0]=0;p.pos[1]=0;});
 if(action==='floor'&&!p.locked){import('./model.js').then(({rotatedHalf})=>commit(()=>p.pos[2]=project.enclosure.t+rotatedHalf(p.dims,p.rot)[2]));}
 if(action==='savePart')workspace.savePart(p).catch(err=>notify(err.message));
});
$('#catalog').addEventListener('click',e=>{const button=e.target.closest('button');if(button?.id==='clearCatalogEmpty')resetCatalog();if(button?.dataset.add)addPart(button.dataset.add);if(button?.dataset.reuse)addPart(null,reusable.find(a=>a.id===button.dataset.reuse));});
$('#assemblyList').addEventListener('click',e=>{const button=e.target.closest('button');if(button?.dataset.select)select(button.dataset.select);if(button?.dataset.visible)commit(()=>{const p=project.parts.find(p=>p.id===button.dataset.visible);p.visible=!p.visible;});});
$('#search').addEventListener('input',renderCatalog);$('#category').addEventListener('change',renderCatalog);
function resetCatalog(){$('#search').value='';$('#category').value='All components';$('#catalogSource').value='all';renderCatalog();$('#search').focus();}
$('#resetCatalog').onclick=resetCatalog;
function tab(which){$('#libraryTab').tabIndex=which==='library'?0:-1;$('#assemblyTab').tabIndex=which==='assembly'?0:-1;$('#libraryView').hidden=which!=='library';$('#assemblyView').hidden=which!=='assembly';$('#libraryTab').setAttribute('aria-selected',which==='library');$('#assemblyTab').setAttribute('aria-selected',which==='assembly');}
$('#libraryTab').onclick=()=>tab('library');$('#assemblyTab').onclick=()=>tab('assembly');
$('#selectEnclosure').onclick=()=>select(null);
$('#projectTitle').addEventListener('change',()=>commit(()=>project.title=$('#projectTitle').value.trim()||'Untitled product',{rebuild:false,inspector:false}));
$('#units').onchange=()=>{commit(()=>project.units=$('#units').value,{rebuild:false});renderCatalog();ui?.sync();};
$('#mode').onchange=()=>{advanced=$('#mode').value==='advanced';setPref('mode',$('#mode').value);document.body.classList.toggle('advanced',advanced);renderInspector();};
$('#theme').onclick=()=>{theme=['light','dark','contrast'][(['light','dark','contrast'].indexOf(theme)+1)%3];document.documentElement.dataset.theme=theme;setPref('theme',theme);studio?.setTheme(theme);$('#theme span').textContent='Theme: '+(theme==='contrast'?'High contrast':theme[0].toUpperCase()+theme.slice(1));notify(`${theme[0].toUpperCase()+theme.slice(1)} theme`);};
$('#newProject').onclick=()=>{if(confirm('Start a new empty project? Export JSON first if you want a separate backup. Undo remains available.'))replaceProject(freshProject());};
function loadDemo(){if(project.parts.length&&!confirm('Load the example in place of this project? Undo remains available.'))return;replaceProject(demoProject());studio?.setViewMode('open');$$('[data-shell]').forEach(b=>b.classList.toggle('active',b.dataset.shell==='open'));notify('Example loaded. Every part is editable.');}
$('#loadDemo').onclick=loadDemo;$('#emptyDemo').onclick=loadDemo;$('#emptyAdd').onclick=()=>{ui?.panel('library',true,{focus:true});tab('library');};
$('#fit').onclick=()=>studio?.fit();$('#camera').onchange=()=>{studio?.fit($('#camera').value);updateViewLabel();};
function updateViewLabel(){ui?.sync();$('#viewName').textContent=`${$('#camera').selectedOptions[0].text} / ${studio?.shellMode==='none'?'parts only':(studio?.shellMode||'open')+' enclosure'}`;}
$$('[data-tool]').forEach(button=>button.onclick=()=>{placement?.cancel();if(button.dataset.tool!=='orbit'&&!studio){notify('3D handles need WebGL. Use the exact transform fields in the inspector.');return;}if(button.dataset.tool!=='orbit'&&(!selected||!project.parts.some(p=>p.id===selected)||project.parts.find(p=>p.id===selected)?.locked)){notify('Select an unlocked part to use the transform handles.');return;}if(button.dataset.tool!=='orbit'&&driven(project,selected)){notify('Use Joints & motion to move this component.');return;}if(studio?.explode>0&&button.dataset.tool!=='orbit'){notify('Return Explode to 0% before editing positions.');return;}workspace?.beforeRefresh();studio?.applyPose({});studio?.setTool(button.dataset.tool);$$('[data-tool]').forEach(b=>b.classList.toggle('active',b===button));transforms?.sync(studio?.tool||'orbit',!!studio?.transform.object);ui?.sync();});
$$('[data-shell]').forEach(button=>button.onclick=()=>{placement?.cancel();studio?.setViewMode(button.dataset.shell);$$('[data-shell]').forEach(b=>b.classList.toggle('active',b===button));updateViewLabel();});
$('#explode').oninput=()=>{placement?.cancel();studio?.setExplode(Number($('#explode').value));$('#explodeValue').textContent=Math.round(Number($('#explode').value)*100)+'%';$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool==='orbit'));ui?.sync();};
$('#grid').onchange=()=>studio?.setGrid($('#grid').checked);
function undo(){placement?.cancel();if(!history.length)return;future.push(snapshot());project=history.pop();workspace?.reset();selected=null;save();refresh();renderCatalog();}
function redo(){placement?.cancel();if(!future.length)return;history.push(snapshot());project=future.pop();workspace?.reset();selected=null;save();refresh();renderCatalog();}
$('#undo').onclick=undo;$('#redo').onclick=redo;
$('#export').onclick=exportDialog;$('#exportProject').onclick=jsonExport;$('#review').onclick=()=>showReview();$('#help').onclick=helpDialog;$('#helpFooter').onclick=helpDialog;
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close();}});
$('#modalBody').addEventListener('click',e=>{
 const button=e.target.closest('button');if(!button)return;const exp=button.dataset.export;if(exp)try{({json:jsonExport,png:pngExport,csv:csvExport,report,stl:stlExport,glb:()=>workspace.viewsDialog(),fabrication:()=>workspace.fabricationDialog(),mp4:()=>workspace.movieDialog(),drawings:()=>workspace.drawingDialog()}[exp])();}catch(err){notify(err.message);}
 if(button.dataset.accept!==undefined){const f=findings[Number(button.dataset.accept)];commit(()=>{project.dismissed=project.dismissed.includes(f.key)?project.dismissed.filter(k=>k!==f.key):[...project.dismissed,f.key];},{rebuild:false});showReview('fit');}
 if(button.dataset.reviewTab)showReview(button.dataset.reviewTab);
 if(button.dataset.finding!==undefined){const f=findings[Number(button.dataset.finding)];if(f.ids.length){$('#modal').close();select(f.ids[0]);}}
 if(button.id==='saveEvidence'){commit(()=>{project.assumptions=$('#assumptions').value.slice(0,12000);project.evidence=$('#evidence').value.slice(0,12000);},{rebuild:false});notify('Assumptions and evidence saved.');}
 if(button.id==='captureBaseline'){const name=prompt('Name this baseline',project.baseline?.name||'Client concept 01');if(name!==null){commit(()=>baseline(project,name),{rebuild:false});showReview('baseline');}}
});
$('#importProject').onclick=()=>$('#jsonFile').click();
$('#jsonFile').onchange=async()=>{const file=$('#jsonFile').files[0];$('#jsonFile').value='';if(!file)return;try{if(file.size>120*1024*1024)throw Error('Project files must be under 120 MB.');const raw=JSON.parse(await file.text()),p=validateProject(raw);if(project.parts.length&&!confirm('Open this project in place of the current one? Undo remains available.'))return;replaceProject(p);notify('Project opened successfully.');}catch(err){notify('Could not open project: '+err.message);}};
document.addEventListener('keydown',e=>{if(e.defaultPrevented||placement?.active()||studio?.transformDraft)return;const edit=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)||document.activeElement?.isContentEditable;if($('#modal').open||edit)return;
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();jsonExport();}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'){e.preventDefault();$('[data-action=duplicate]')?.click();}
 if(e.key==='Delete'||e.key==='Backspace'){if(selected){e.preventDefault();$('[data-action=delete]')?.click();}}
 if(!e.ctrlKey&&!e.metaKey&&!e.altKey&&['g','r'].includes(e.key.toLowerCase())){e.preventDefault();$('[data-tool="'+(e.key.toLowerCase()==='g'?'translate':'rotate')+'"]')?.click();}if(e.key.toLowerCase()==='f')studio?.fit();if(e.key.toLowerCase()==='d'&&!e.ctrlKey&&!e.metaKey){ui?.panel('inspector',true);const field=$('[data-prop="dims.0"]')||$('[data-prop="enclosure.w"]');field?.focus();field?.select();}
});

document.addEventListener('visibilitychange',()=>{if(document.hidden&&saveTimer){clearTimeout(saveTimer);saveTimer=null;const value=snapshot();saveChain=saveChain.catch(()=>{}).then(()=>saveProject(value)).catch(()=>status('Save failed · export JSON','error'));}});
window.addEventListener('error',e=>{if(e.error?.message)notify('Action failed: '+e.error.message);});
window.addEventListener('unhandledrejection',e=>notify('Action failed: '+(e.reason?.message||String(e.reason))));
window.addEventListener('beforeunload',e=>{if($('#saveState').dataset.state!=='saved'){e.preventDefault();e.returnValue='';}});

