try{studio=new Studio($('#viewport'),{select,editSurface:(id,feature)=>workspace?.editSurface(id,feature),point:p=>workspace?.point(p),geometry:errors=>workspace?.geometry(errors),tool:(tool,attached)=>transforms?.sync(tool,attached),transformPreview:(...args)=>transforms?.preview(...args),transformCommit:(id,pos,rot)=>{const p=project.parts.find(p=>p.id===id);if(!p||p.locked||driven(project,id))return;try{commit(()=>{p.pos=pos.map(n=>+n.toFixed(6));p.rot=rot.map(n=>+n.toFixed(6));});}catch(err){notify(err.message);}const saved=project.parts.find(p=>p.id===id);if(saved)transforms?.preview(id,saved.pos,saved.rot,[],true);}});studio.setTheme(theme);}catch(err){$('#webglError').hidden=false;$('#webglError').textContent='3D view could not start. Enable WebGL 2 / hardware acceleration and reload. Your part records and project exports remain available. '+err.message;console.error(err);}
