 fromCard:card=>card.dataset.add?catalogPart(card.dataset.add):catalogPart(null,reusable.find(p=>p.id===card.dataset.reuse)),
 prepare:()=>{if(failedLoad)throw Error('Open a valid project or choose New Project before editing.');workspace.beforeRefresh();if(studio.explode){studio.setExplode(0);notify('Returned to the assembled view for placement.');}if(project.enclosure.enabled&&studio.shellMode==='none')studio.setViewMode('open');if(studio.shellMode==='open'&&['hinge','slide'].includes(project.enclosure.closure?.type)){studio.setViewMode('ghost');notify('Transparent view shows the lid at its saved position for accurate placement.');}studio.applyPose({});if(studio.section){studio.setSection('none',0);notify('Section view cleared for placement.');}$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool==='orbit'));$$('[data-shell]').forEach(b=>b.classList.toggle('active',b.dataset.shell===studio.shellMode));$('#explode').value=0;$('#explodeValue').textContent='0%';updateViewLabel();},
 reveal:dragging=>{if(innerWidth<=1100)ui?.panel('inspector',false,{persist:false});if(innerWidth<=720&&!dragging)ui?.panel('library',false,{persist:false});}
